ALTER TABLE public.garage_request_stats_hourly ADD COLUMN last_request_at timestamptz;
CREATE OR REPLACE FUNCTION public.operator_garage_overview(_garage_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH own AS(SELECT id FROM garages WHERE id=_garage_id AND operator_id=auth.uid()),s AS(SELECT h.* FROM garage_request_stats_hourly h JOIN own ON own.id=h.garage_id),m AS(SELECT h.model,sum(h.requests) requests FROM garage_model_stats_hourly h JOIN own ON own.id=h.garage_id WHERE h.hour>=date_trunc('week',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' GROUP BY h.model) SELECT CASE WHEN EXISTS(SELECT 1 FROM own) THEN jsonb_build_object('today',coalesce((SELECT sum(spend_usd) FROM s WHERE hour>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0),'week',coalesce((SELECT sum(spend_usd) FROM s WHERE hour>=date_trunc('week',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0),'total',coalesce((SELECT sum(spend_usd) FROM s),0),'last_request_at',(SELECT max(last_request_at) FROM s WHERE requests>0),'last_request_hour',(SELECT max(hour) FROM s WHERE requests>0),'response_ms',(SELECT percentile_cont(0.5) WITHIN GROUP(ORDER BY ttft_ms_p50) FROM s WHERE hour>=now()-interval '7 days' AND ttft_ms_p50>0),'daily',(SELECT jsonb_agg(jsonb_build_object('day',d.day::date,'requests',coalesce((SELECT sum(requests) FROM s WHERE hour>=d.day AND hour<d.day+interval '1 day'),0)) ORDER BY d.day) FROM generate_series(date_trunc('day',now() AT TIME ZONE 'UTC')-interval '13 days',date_trunc('day',now() AT TIME ZONE 'UTC'),interval '1 day') d(day)),'models',coalesce((SELECT jsonb_agg(jsonb_build_object('model',model,'requests',requests)) FROM m),'[]'::jsonb)) END $$;
CREATE OR REPLACE FUNCTION public.operator_garage_activity() RETURNS TABLE(garage_id uuid,period text,requests bigint,prompt_tokens bigint,completion_tokens bigint,recorded_spend numeric,estimated_earnings numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT g.id,w.period,coalesce(sum(s.requests),0)::bigint,coalesce(sum(s.prompt_tokens),0)::bigint,coalesce(sum(s.completion_tokens),0)::bigint,coalesce(sum(s.spend_usd),0),coalesce(sum(((s.prompt_tokens-s.dedicated_prompt_tokens)*coalesce(m.pool_input_cost_per_million,g.pool_input_cost_per_million)+s.dedicated_prompt_tokens*coalesce(m.dedicated_input_cost_per_million,g.dedicated_input_cost_per_million)+(s.completion_tokens-s.dedicated_completion_tokens)*coalesce(m.pool_output_cost_per_million,g.pool_output_cost_per_million)+s.dedicated_completion_tokens*coalesce(m.dedicated_output_cost_per_million,g.dedicated_output_cost_per_million))/1000000),0)
FROM garages g CROSS JOIN(VALUES('7d',interval '7 days'),('30d',interval '30 days')) w(period,span) LEFT JOIN garage_model_stats_hourly s ON s.garage_id=g.id AND s.hour>=now()-w.span LEFT JOIN garage_models m ON m.garage_id=s.garage_id AND regexp_replace(m.model,'[^A-Za-z0-9._-]','-','g')=s.model WHERE g.operator_id=auth.uid() OR public.has_role(auth.uid(),'admin') GROUP BY g.id,w.period $$;
COMMENT ON COLUMN public.garages.first_models_at IS 'DEPRECATED: recommendation banner replaced by inline My garage suggestions';
COMMENT ON COLUMN public.garages.offer_page_seen_at IS 'DEPRECATED: separate offer page replaced by inline My garage suggestions';